   "text": "你只需要带走一句话：**对称不是「好看」，而是一整套「把图形搬回原位却不留痕迹」的操作，这些操作自己构成一个封闭的小世界，叫群。**\n写成群之后，「哪些变换被允许」就从含糊的印象变成一份可以逐条检查的清单：哪些能接起来、哪些能撤销、哪些能交换顺序。\n这份清单还要走两步。第一步「连续化」：若允许的角度可以任意小，清单就变成李群，它在「什么都不做」附近的切线叫李代数，物理里那些生成元和对易关系都长在这儿。第二步「落在具体向量上」：让抽象的群去操作真实的向量空间，这叫表示论；拆不开的最小积木叫不可约表示，粒子分类就是按它分的。\n最后点名三个由「保持什么不变」定义的群：保长度的 O(n)、保复内积的 U(n)、保辛形式的 Sp(n)。"
