   "orig": "反方向呢？任给一个非奇异的 n×n 实对称矩阵，能不能化成克罗内克 δ 的分量形式？不能完全做到——用实的线性坐标变换不行。它能化成的是同样的形状，只是主对角线上有些项是 1、有些项是 −1。1 的个数 p 与 −1 的个数 q 是不变量：换别的实线性变换也改不了。这个不变量 (p, q) 叫 g 的符号差（signature）。（有时把 p−q 叫符号差；有时干脆写成 +…+−…−，两种符号各取适当个数。）其实对奇异的 g 也成立，只是这时主对角线上还要有些 0，0 的个数也一并计入符号差，连同 1 的个数与 −1 的个数。若只有 1，即 g 非奇异且 q=0，就说 g 是正定的。p=1 而 q≠0（或 q=1 而 p≠0）的非奇异 g 叫洛伦兹型的，以此纪念荷兰物理学家 H. A. 洛伦兹（H. A. Lorentz，1853–1928）——他在这方面的重头工作为相对论打下了一块基石；见 17.6–9 节与 18.1–3 节。",
